"""Documents, policies and operational pages for HeyDock."""

def add_document_pages(ns):
 page,hero,section,faq,cards,steps,link=ns['page'],ns['hero'],ns['section'],ns['faq'],ns['cards'],ns['steps'],ns['link']
 E=ns['E']
 CONTACT_EMAIL=ns['CONTACT_EMAIL']
 OPERATOR_NAME=ns['OPERATOR_NAME']
 OPERATOR_NUMBER=ns['OPERATOR_NUMBER']
 OPERATOR_OFFICE=ns['OPERATOR_OFFICE']
 OPERATOR_JURISDICTION=ns.get('OPERATOR_JURISDICTION','')
 OPERATOR_VAT=ns.get('OPERATOR_VAT','')
 PUBLIC_BUILD=ns['PUBLIC_BUILD']
 operator_html=ns['operator_html']()
 contact_channel=ns['contact_channel']
 missing=ns['missing_disclosures']

 # --- Documents hub ---
 hub=hero('DOCUMENTS & POLICIES','Policies and working practices.<br><em>In one place.</em>','Short links to website policies, how engagements work, and MSP onboarding information.','Send an enquiry','/contact.html')
 hub+=section('WEBSITE POLICIES','How this site and your data are handled.','',cards([
  ('/privacy.html','Privacy notice','Enquiry handling, processors and your rights.','lock'),
  ('/cookies.html','Cookies &amp; storage','What this site actually uses in the browser.','browser'),
  ('/terms.html','Website terms','Use of the site, IP and when enquiries become agreements.','clipboard'),
  ('/accessibility.html','Accessibility','Features, limitations and how to report issues.','screen'),
  ('/complaints.html','Complaints','How to raise a concern and how it is handled.','chat'),
 ]))
 hub+=section('WORKING WITH HEYDOCK','Delivery, support and data handling.','',cards([
  ('/how-we-work.html','How we work','From enquiry and quote through delivery and handover.','workflow'),
  ('/support-and-escalation.html','Support &amp; escalation','How to request help and how urgency is assessed.','headset'),
  ('/security-and-data-handling.html','Security &amp; data handling','Site access, credentials and customer information.','shield'),
 ]),'pale')
 hub+=section('MSP ONBOARDING','Partner-facing process information.','',cards([
  ('/vendor-onboarding.html','Vendor onboarding','White-label communication, scope, reporting and escalation.','people'),
  ('/partners.html','IT partners overview','What partners can book and how fulfilment works.','pin'),
 ]))
 hub+=section('DOWNLOADS','Public files.','','<div class="prose"><p>No approved public downloads are published on this site yet. NDAs, MSAs, statements of work, SLAs, DPAs, insurance evidence and internal templates are discussed privately when applicable and are not hosted here unless separately approved.</p></div>')
 page('documents.html','Documents and policies','HeyDock website policies, delivery practices and MSP onboarding information.',hub)

 # --- Privacy ---
 privacy=hero('PRIVACY NOTICE','How enquiry and website data<br><em>is handled.</em>','This notice explains personal data processing for the HeyDock website and contact form. It is not a substitute for contractual data-processing terms that may apply to a signed engagement.')
 privacy+=section('CONTROLLER','Who is responsible.','', '<div class="prose">'+operator_html+
  '<p>HeyDock is the customer-facing brand for this website. The legal operator named above (when published) is the controller for website enquiry data. If an operator name is not yet published, use the enquiry form for privacy requests and treat this notice as describing the intended processing model.</p></div>')
 privacy+=section('WHAT WE COLLECT','Website and enquiry information.','','<div class="prose"><h3>Enquiry form</h3><p>When you submit <a href="/contact.html">the contact form</a>, we process: customer type, service interest, company name, your name, business email, country/city, preferred timing, budget indication, and the free-text description of your requirement. A hidden honeypot field may be submitted for spam checks and is not used for marketing.</p><h3>Technical request data</h3><p>Hosting and edge delivery (intended production host: Cloudflare Pages and Pages Functions) may process IP address, user agent, request path, timestamps and similar connection metadata under the host’s terms. This site does not add advertising pixels or third-party analytics scripts in the generated pages.</p><h3>What we ask you not to send</h3><p>Do not include passwords, authentication secrets, payroll files, special-category data or unnecessary personal data about third parties in the enquiry form.</p></div>','pale')
 privacy+=section('WHY WE USE IT','Purposes and lawful bases.','','<div class="prose"><p>We use enquiry details to acknowledge and respond to your request, assess coverage and scope, prepare a quote where appropriate, and keep records of business correspondence.</p><ul><li><strong>Steps prior to a contract</strong> (UK GDPR Article 6(1)(b)) where you ask HeyDock to discuss or quote for services.</li><li><strong>Legitimate interests</strong> (Article 6(1)(f)) in operating a business contact channel, preventing spam/abuse, and improving clarity of responses, balanced against your rights.</li></ul><p>The form checkbox confirms you understand the enquiry will be sent so HeyDock can respond. It is not consent for marketing newsletters, and submitting an enquiry does not create a paid engagement.</p></div>')
 privacy+=section('RECIPIENTS AND PROCESSORS','Who receives enquiry data.','','<div class="prose"><p>Enquiry payloads are posted from your browser to a same-origin Cloudflare Pages Function (<code>/api/enquiry</code>). The Function validates input and sends an email through <strong>Resend</strong> to the monitored business inbox configured as <code>HEYDOCK_TO_EMAIL</code>, using the verified sender <code>HEYDOCK_FROM_EMAIL</code>. Your email address is set as the reply-to address so the business can respond.</p><p>Cloudflare (hosting/Functions) and Resend (email delivery) act as processors or service providers for those technical steps. Mailbox providers for the monitored inbox may also store the message. Staff or contractors handling enquiries for HeyDock may read the message to respond.</p><p>We do not sell enquiry data. We do not place enquiry text in page URLs or browser local storage via this site’s own scripts.</p></div>','pale')
 privacy+=section('INTERNATIONAL TRANSFERS','Where data may be processed.','','<div class="prose"><p>Cloudflare and Resend may process data in the United Kingdom, European Economic Area, United States or other locations depending on their service configuration. Where a restricted transfer applies, the relevant provider’s transfer mechanism (such as standard contractual clauses) applies under their terms. Confirm the live provider regions in each vendor’s current documentation after production credentials are issued.</p></div>')
 privacy+=section('RETENTION','How long information is kept.','','<div class="prose"><p>Enquiry emails are retained in the business mailbox and any Resend dashboard history according to those systems’ settings and ordinary business correspondence needs—typically long enough to complete the sales discussion and related compliance records, then deleted or archived under the operator’s email retention practice. Server validation logs for the Function are limited to non-content failure codes and must not include enquiry bodies or API keys. Exact purge schedules should be confirmed by the operator once production mailboxes are live.</p></div>')
 privacy+=section('YOUR RIGHTS','Access, correction and complaints.','','<div class="prose"><p>Depending on applicable UK data protection law, you may have rights to access, rectify, erase, restrict or object to certain processing, and to data portability where relevant. To exercise these rights, contact '+contact_channel('privacy')+'. You may also complain to the Information Commissioner’s Office (ICO) at <a href="https://ico.org.uk/">ico.org.uk</a>.</p></div>','pale')
 if not PUBLIC_BUILD and missing:
  privacy+=section('PREVIEW DIAGNOSTIC','Maintainer notice only.','','<div class="prose notice-panel"><p>This preview build is missing verified disclosures: '+E(', '.join(missing))+'. These notes are for maintainers and should not appear on an authorised public production site.</p></div>')
 page('privacy.html','Privacy notice','How HeyDock processes website enquiry data, including Cloudflare Functions, Resend delivery and your rights.',privacy)

 # --- Cookies ---
 cookies=hero('COOKIES &amp; STORAGE','What this website uses<br><em>in your browser.</em>','A factual description of cookies and storage based on the current generated site and documented hosting model.')
 cookies+=section('SITE-CONTROLLED STORAGE','What our pages do.','','<div class="prose"><p>The HeyDock HTML, CSS and JavaScript in this repository do <strong>not</strong> set advertising or analytics cookies and do not write enquiry fields to <code>localStorage</code> or <code>sessionStorage</code>.</p><p>Catalogue filters on the software page operate in the current page document only. Custom select disclosures are progressive enhancements around native form controls.</p></div>')
 cookies+=section('HOSTING AND NETWORK','What may still occur.','','<div class="prose"><p>Cloudflare Pages (the intended production host) may set or rely on cookies or similar technologies that are strictly necessary for security, load balancing or platform operation. Those behaviours are controlled by Cloudflare and should be re-checked on the live production hostname after deployment.</p><p>Private preview or sign-in gateways used during development are separate from the public Pages deployment and may use their own authentication cookies. They are not part of the intended public visitor experience.</p></div>','pale')
 cookies+=section('CHANGES','If we add optional cookies later.','','<div class="prose"><p>If analytics or non-essential cookies are introduced later, this page and any required consent mechanism must be updated before those technologies are enabled. This task does not add an analytics product or cookie banner.</p></div>')
 page('cookies.html','Cookies and browser storage','What cookies and browser storage the HeyDock website uses, and what to re-check after deployment.',cookies)

 # --- Terms ---
 terms=hero('WEBSITE TERMS','Using the HeyDock website.','These terms cover use of this website and how enquiries relate to paid work. They are not a substitute for a signed proposal, statement of work or service agreement.')
 terms+=section('COMPANY INFORMATION','Legal operator.','', '<div class="prose">'+operator_html+'<p>HeyDock is presented as a standalone brand across this website. Marketing pages do not present HeyDock as a secondary trading style of another consumer brand. Where a legal operator is published above, that entity is responsible for the site and for contracts it enters into.</p></div>')
 terms+=section('WEBSITE USE','Licence and acceptable use.','','<div class="prose"><p>You may view and download materials from this site for your internal business evaluation of HeyDock services. You must not misuse the site, attempt to disrupt it, scrape it aggressively, or submit unlawful, abusive or deceptive content through forms.</p><p>Website content is provided for general information. Service availability, pricing, attendance times and support commitments are confirmed only in writing for a specific engagement.</p></div>','pale')
 terms+=section('INTELLECTUAL PROPERTY','Brand and site materials.','','<div class="prose"><p>HeyDock branding, site design and original text are protected by applicable intellectual-property laws. Software products listed in the catalogue may be third-party products; listing a category does not transfer ownership of that product. Do not copy the site wholesale or use the HeyDock marks in a way that suggests endorsement without permission.</p></div>')
 terms+=section('ENQUIRIES AND QUOTES','When an engagement starts.','','<div class="prose"><p>Submitting the website enquiry form sends a request for review. It does <strong>not</strong> book an engineer, open a support ticket under an SLA, or create a binding contract.</p><p>An engagement begins only when both parties agree the scope and commercial terms in a written proposal, statement of work, order form or other signed/accepted service agreement. Until then, either party may decline to proceed.</p><p>Quotes are based on the information supplied. Material changes to location, access, scope, timing or equipment may require a revised quote.</p></div>','pale')
 terms+=section('PAID WORK','Governing documents.','','<div class="prose"><p>Signed proposals and service agreements govern deliverables, fees, expenses, service hours, escalation, liability and termination for paid work. Website terms do not override those documents. Partner white-label rules, if any, are set out in the partner agreement and work orders.</p></div>')
 terms+=section('LIABILITY FOR THE WEBSITE','Information accuracy.','','<div class="prose"><p>We aim to keep website information accurate but do not warrant that every page is complete or current. To the fullest extent permitted by law, HeyDock is not liable for decisions made solely in reliance on marketing pages without a written agreement. Nothing in these terms excludes liability that cannot be excluded under applicable law.</p></div>','pale')
 page('terms.html','Website terms','Terms for using the HeyDock website, intellectual property, and when enquiries become agreed engagements.',terms)

 # --- Accessibility ---
 a11y=hero('ACCESSIBILITY','Navigating HeyDock<br><em>more easily.</em>','Accessibility features built into this site, known limitations, and how to report problems.')
 a11y+=section('FEATURES PRESENT','What the current site includes.','','<div class="prose"><ul><li>Skip link to main content</li><li>Keyboard-operable navigation, including Escape to close the mobile menu</li><li>Visible focus styles</li><li>Labelled form controls and native validation</li><li>Enquiry sending, success and error status messages</li><li>Responsive layouts and touch-friendly controls</li><li>Reduced-motion preferences respected for decorative motion</li><li>Software catalogue result counts announced for filters</li></ul><p>This list describes implemented features. It is <strong>not</strong> a claim of WCAG conformance or a completed accessibility audit.</p></div>')
 a11y+=section('KNOWN LIMITATIONS','Honest constraints.','','<div class="prose"><ul><li>No formal third-party accessibility audit has been completed for this release.</li><li>Custom select disclosures progressively enhance native selects; if enhancement fails, native controls remain.</li><li>Complex service pages are text-heavy; structure relies on headings and lists rather than a separate easy-read edition.</li><li>PDF or other downloadable policy packs are not yet published; when added they will need their own accessibility review.</li></ul></div>','pale')
 a11y+=section('REPORT A PROBLEM','How to contact us.','','<div class="prose"><p>If you encounter a barrier, email or write via '+contact_channel('accessibility')+'. Please include the page URL, the device/browser if known, and what you were trying to do. We will acknowledge the report through the same channel and aim to assess a practical fix or workaround.</p></div>')
 page('accessibility.html','Accessibility statement','Accessibility features on the HeyDock website, limitations, and how to report problems.',a11y)

 # --- Complaints ---
 complaints=hero('COMPLAINTS','Tell us when something<br><em>is wrong.</em>','How to raise a complaint about HeyDock website handling or a service discussion. Contractual dispute processes in a signed agreement take priority for that engagement.')
 complaints+=section('HOW TO RAISE A COMPLAINT','What to send.','','<div class="prose"><p>Contact '+contact_channel('complaints')+'. Include:</p><ul><li>Your name, company and preferred reply email</li><li>A clear description of the issue and when it happened</li><li>Any relevant enquiry reference, quote or site location</li><li>The outcome you are seeking</li></ul><p>Do not include passwords or unnecessary sensitive personal data.</p></div>')
 complaints+=section('WHAT HAPPENS NEXT','Acknowledgement and investigation.','','<div class="prose"><p>We review complaints sent through the published contact channel, acknowledge receipt, and investigate with the people involved in the enquiry or delivery discussion. You should receive a substantive response once the facts are checked.</p><p><strong>No fixed public response-time targets are published on this page</strong> because HeyDock has not approved numbered complaint SLAs for the website. If a signed client agreement sets complaint or escalation timelines, those contractual terms apply to that client.</p></div>','pale')
 complaints+=section('ESCALATION','If you remain dissatisfied.','','<div class="prose"><p>Ask for the complaint to be reviewed by a more senior contact via the same channel. For privacy complaints you may also contact the ICO. For contractual disputes, follow the dispute clause in your agreement.</p></div>')
 page('complaints.html','Complaints','How to raise a complaint with HeyDock, what to include, and how escalation works.',complaints)

 # --- How we work (replace/expand) ---
 how=hero('HOW WE WORK','From request to handover<br><em>without guesswork.</em>','The client journey for on-site support, dispatch and project work. Commercial commitments appear only in your written quote or agreement.')
 how+=section('CLIENT JOURNEY','The usual sequence.','',steps([
  ('Request','You send an enquiry with location, timing, scope and access context.'),
  ('Scope','We clarify skills, exclusions, dependencies and any partner branding rules.'),
  ('Written quote','You receive commercial terms for the defined work—not a verbal blanket promise.'),
  ('Schedule','Once accepted, attendance or delivery windows are booked with named contacts.'),
  ('Deliver','Work follows the approved scope; changes are raised before extra effort proceeds.'),
  ('Handover','You receive evidence, open items and sign-off appropriate to the task.'),
 ]))
 how+=section('QUOTE INPUTS','What we need from you.','','<div class="check-grid"><div><b>✓</b>Site location and access requirements</div><div><b>✓</b>Preferred dates or windows</div><div><b>✓</b>Task scope, skills and success criteria</div><div><b>✓</b>Equipment, parts and escalation owner</div></div>','pale')
 how+=section('SITE ACCESS AND CHANGES','Keeping work controlled.','','<div class="prose"><p>Site contacts, permits, parking, induction and chaperone rules must be stated before attendance. Engineers follow the authorised work order. If on-site conditions differ, the change is documented and escalated rather than improvising production changes.</p><p>Who signs off: the named customer or partner approver identified in the work order. What you receive: visit or project evidence agreed in advance (for example time on site, tasks completed, test results, asset notes and outstanding issues).</p></div>')
 how+=section('RELATED PAGES','Support, security and policies.','',cards([
  ('/support-and-escalation.html','Support &amp; escalation','How ongoing issues are raised and prioritised.','headset'),
  ('/security-and-data-handling.html','Security &amp; data handling','Credentials, equipment and information handling.','shield'),
  ('/documents.html','Documents &amp; policies','Legal and operational page index.','clipboard'),
 ]))
 page('how-we-work.html','How we work','HeyDock client journey from enquiry and written quote through scheduling, delivery and handover.',how)

 # --- Support & escalation ---
 support=hero('SUPPORT &amp; ESCALATION','How to ask for help<br><em>clearly.</em>','Use this page for the general support model. Coverage hours and response targets are those written into your client or partner agreement—not generic website promises.')
 support+=section('REQUESTING SUPPORT','What to provide.','','<div class="prose"><p>Contact the channel named in your agreement, or '+contact_channel('support')+' for pre-contract questions. Include impact, location, affected systems/users, recent changes, and any ticket or work-order reference.</p></div>')
 support+=section('URGENCY AND ESCALATION','How HeyDock assesses priority.','','<div class="prose"><p>We assess urgency from business impact, safety/risk, number of users affected, and whether a workaround exists. Escalation follows the contacts named for your engagement (for example service desk → technical lead → account owner). Partners retain end-customer communication unless the work order says otherwise.</p></div>','pale')
 support+=section('COVERAGE COMMITMENTS','Where they are defined.','','<div class="prose"><p>Support hours, on-site attendance targets, penalties and 24/7 cover are <strong>not</strong> advertised as universal website promises. They are set out only in the agreement that applies to your account. If no agreement exists yet, an enquiry starts a scoping discussion only.</p></div>')
 page('support-and-escalation.html','Support and escalation','How to request HeyDock support, how urgency is assessed, and where coverage commitments are defined.',support)

 # --- Security & data handling ---
 security=hero('SECURITY &amp; DATA HANDLING','Practical controls<br><em>for customer work.</em>','Customer-facing information about access, credentials and information handling during HeyDock engagements. Practices needing owner confirmation are flagged below.')
 security+=section('SITE ACCESS','On-site behaviour.','','<div class="prose"><p>Engineers attend only with an approved work order and site instructions. They should follow host security rules, wear required identification, and limit access to areas needed for the task. Photography and asset capture follow the customer or partner rules stated in the work order.</p></div>')
 security+=section('CREDENTIALS AND SYSTEMS','What we expect.','','<div class="prose"><p>Do not send passwords or privileged credentials through the public website enquiry form. Prefer customer-controlled accounts, time-limited access or an agreed secure channel named in the engagement. Access should be removed or rotated after the work where the customer controls identity systems.</p></div>','pale')
 security+=section('EQUIPMENT AND DATA','Handling and return.','','<div class="prose"><p>Customer equipment and media are handled only as authorised. Spares and failed parts follow the ownership and return rules in the work order. Customer data obtained for a task should be used only for that task; deletion or return follows the method agreed for the engagement (for example wipe confirmation, physical return, or customer-led revocation of access).</p></div>')
 security+=section('INCIDENTS','Reporting problems.','','<div class="prose"><p>Suspected security incidents related to a HeyDock engagement should be reported immediately through the escalation contacts in your agreement or via '+contact_channel('security')+'. Preserve relevant logs where safe to do so and avoid circulating credentials in email threads.</p></div>')
 security+=section('CONFIRMATION FLAGS','Owner review required.','','<div class="prose notice-panel"><p><strong>Flagged for owner confirmation before stronger public claims:</strong></p><ul><li>Named security certifications, accreditations or audit reports</li><li>Company-wide encryption or device-management standards</li><li>Formal incident-response SLAs or cyber-insurance limits</li><li>Standard DPA templates published for download</li></ul><p>Until confirmed, this page describes process expectations only and does not claim certification or guaranteed outcomes.</p></div>','pale')
 page('security-and-data-handling.html','Security and data handling','How HeyDock handles site access, credentials, equipment and customer data during engagements.',security)

 # --- Vendor onboarding ---
 vendor=hero('VENDOR ONBOARDING','MSP onboarding<br><em>without surprises.</em>','How IT providers start white-label work with HeyDock. Document packs and insurance evidence are discussed privately when needed—they are not automatically published here.')
 vendor+=section('ONBOARDING PROCESS','Typical steps.','',steps([
  ('Intro &amp; fit','Confirm services, geographies of interest and commercial model.'),
  ('Contacts','Exchange escalation owners, branding rules and reporting format.'),
  ('Paperwork','Discuss NDA, MSA, SOW, SLA, DPA or insurance evidence when applicable.'),
  ('First work order','Pilot a clearly scoped visit or project before wider volume.'),
 ]))
 vendor+=section('WHITE-LABEL OPERATIONS','Communication and control.','','<div class="prose"><p>Partners keep the customer relationship unless a work order says otherwise. HeyDock follows partner branding and communication rules agreed in writing. Scope changes require partner approval. Reporting and escalation paths are named per work order.</p></div>','pale')
 vendor+=section('DOCUMENTS AND INSURANCE','What can be discussed.','','<div class="prose"><p>An NDA, master services agreement, statement of work, service levels, data-processing terms or insurance evidence <strong>can be discussed or shared privately</strong> when applicable to a partnership. This website does <strong>not</strong> imply that any specific document or insurance certificate already exists or is available for public download unless a verified file is linked from <a href="/documents.html">Documents &amp; policies</a>.</p></div>')
 vendor+=section('NEXT STEP','Start the conversation.','',link('/contact.html?audience=partner','Discuss white-label support')+' '+link('/documents.html','Browse documents &amp; policies','btn ghost')+' '+link('/partners.html','Partner overview','btn ghost'))
 page('vendor-onboarding.html','Vendor onboarding for MSPs','How MSPs onboard with HeyDock for white-label dispatch, reporting and private agreement discussions.',vendor)
